import logging
import os
from moler.device import DeviceFactory
from taf.rfrl.bts.devices.cu.generic_cu import GenericCu, login_logout
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.utilities.test_config import get_log_path
from taf.rfrl.bts.connections import device_aliases
from taf.rfrl.utilities.transfer_files import download_files
from taf.rfrl.bts.common.tcpdump_collection import start_tcpdump_on_device, stop_tcpdump_on_device


class CuLogsCollector(GenericCu):
    """CU(Centralized Unit) keywords for gNB"""

    def collect_symptom_report(self, bts_id=0, log_dir=None, timeout=180):
        """
        Save and download symptom report.

        :param bts_id: id of bts from which the symptom report will be collected
        :param log_dir: directory where report will be collected
        :param timeout: timeout for _save_symptom_report
        """
        report_file_path = self._save_symptom_report(bts_id=bts_id, timeout=timeout)
        self._download_symptom_report(report_file_path=report_file_path, bts_id=bts_id, log_dir=log_dir)

    @load_moler_configuration_from_tl()
    def _download_symptom_report(self, report_file_path, bts_id=0, log_dir=None, timeout=180):
        """
        Download symptomreport.zip file to log directory on the local machine.

        :param report_file_path: path to report file on bts
        :param bts_id: id of bts from which the symptom report will be downloaded
        :param log_dir: directory where report will be collected
        :param timeout: timeout for scp.
        """
        if log_dir is None:
            log_dir = get_log_path()

        gnb = DeviceFactory.get_device(format(device_aliases.ssh_gnb_cu.format(bts_id)))
        gnb.goto_state('FCT')

        mv_cmd = gnb.get_cmd(cmd_name='mv', cmd_params={'src': os.path.abspath(report_file_path), 'dst': "/tmp"})
        mv_cmd()

        download_files(local_dir=log_dir,
                       remote_file=os.path.basename(report_file_path),
                       remote_dir="/tmp",
                       device_name=device_aliases.ssh_gnb_cu.format(bts_id),
                       from_state='FCT',
                       timeout=timeout)

    @load_moler_configuration_from_tl()
    def download_bip_logs_from_upue_interface(self, interface, log_file_name, log_file_path=r"/home/robot/", bts_id=0, log_dir=None, timeout=120):
        """
        Download pcap bib logs from gNB to local machine.(Works only for local mode)

        :param log_file_name: name of the file logs will be saved to
        :param interface: CPIF VM interface
        :param log_file_path: path to directory on UPUE from where file will be download.
        :param timeout: timeout for scp.
        :param log_dir: path to directory where bip logs will be download
        :return:    directory where the logs are saved
        """
        if log_dir is None:
            log_dir = get_log_path()

        gnb = DeviceFactory.get_device(format(device_aliases.ssh_gnb_cu.format(bts_id)))
        gnb.goto_state(interface)
        mkdir_cmd = gnb.get_cmd(cmd_name='mkdir', cmd_params={'path': "/tmp/logs"})
        mkdir_cmd()
        mv_cmd = gnb.get_cmd(cmd_name='mv', cmd_params={'src': os.path.join(log_file_path, log_file_name),
                                                        'dst': "/tmp/logs"})
        mv_cmd()
        download_files(local_dir=log_dir,
                       remote_file=log_file_name,
                       remote_dir="/tmp/logs",
                       device_name=device_aliases.ssh_gnb_cu.format(bts_id),
                       from_state=interface,
                       timeout=timeout)
        rm = gnb.get_cmd(cmd_name="rm", cmd_params={"file": "/tmp/logs", "options": '-rf'})
        rm()
        return log_dir

    @load_moler_configuration_from_tl()
    def _save_symptom_report(self, bts_id=0, timeout=180):
        """
        Save symptom report.

        :param bts_id: id of bts from which the symptom report will be saved
        :param timeout: timeout for save_symptom_report
        """
        gnb = DeviceFactory.get_device(format(device_aliases.ssh_gnb_cu.format(bts_id)))
        gnb.goto_state("FSCLISH")
        save_symptom_report_cmd = gnb.get_cmd(cmd_name='save_symptom_report')
        results = save_symptom_report_cmd(timeout)
        log_path = results['PATH']
        logging.info("CU log collected in {}".format(log_path))
        return log_path

    @login_logout
    def download_snapshot_from_cu(self, path, request_timeout=300, operation_timeout=600, bts_id=0):
        """
        Gets local snapshot and saves it under given directory.
        :param path: absolute directory path where snapshot will be saved
        :param request_timeout: timeout in seconds for sending request to OAM, defaults to None
        :param operation_timeout: timeout in seconds for getting snapshot, defaults to 600.0
        :param bts_id: ID of BTS
        :return: None
        """
        self.cu.get_local_snapshot(path, request_timeout, operation_timeout)
        logging.debug("Snapshot collected successfully")

    @load_moler_configuration_from_tl()
    def start_tcpdump_collection_on_cpif_interface(self, interface, capture_file, count=0,
                                                   duration=0, background=False, timeout=300, bts_id=0,
                                                   additional_options=None):
        """
        Start tcpdump collection on the selected interface of the CPIF Virtual Machine
        :param interface:       CPIF VM interface
        :param capture_file:    Name of the capture file
        :param count:           Number of packets to be captured
        :param duration:        Duration of tcpdump in seconds
        :param background:      Flag if tcpdump should run in the background
        :param timeout:         Timeout in seconds to be set for the tcpdump command
        :param bts_id:          BTS ID - related to TestLine configuration
        :param additional_options: options be added to tcpdump command
        """
        gnb = DeviceFactory.get_device(format(device_aliases.ssh_gnb_cu.format(bts_id)))
        gnb.goto_state("CPIF")
        start_tcpdump_on_device(device=gnb, interface=interface, capture_file=capture_file, count=count,
                                duration=duration, background=background, timeout=timeout,
                                additional_options=additional_options, execute_by_sudo=True)

    @load_moler_configuration_from_tl()
    def start_tcpdump_collection_on_upue_interface(self, interface, capture_file, count=0,
                                                   duration=0, background=False, timeout=300, bts_id=0,
                                                   additional_options=None):
        """
        Start tcpdump collection on the selected interface of the UPUE Virtual Machine
        :param interface:       UPUE VM interface
        :param capture_file:    Name of the capture file
        :param count:           Number of packets to be captured
        :param duration:        Duration of tcpdump in seconds
        :param background:      Flag if tcpdump should run in the background
        :param timeout:         Timeout in seconds to be set for the tcpdump command
        :param bts_id:          BTS ID - related to TestLine configuration
        :param additional_options: options be added to tcpdump command
        """
        gnb = DeviceFactory.get_device(format(device_aliases.ssh_gnb_cu.format(bts_id)))
        gnb.goto_state("UPUE")
        start_tcpdump_on_device(device=gnb, interface=interface, capture_file=capture_file, count=count,
                                duration=duration, background=background, timeout=timeout,
                                additional_options=additional_options, execute_by_sudo=True)

    def start_tcpdump_collection_on_x2_cpif_interface(self, capture_file, count=0, duration=0,
                                                      background=False, timeout=300, bts_id=0,
                                                      additional_options=None):

        self.start_tcpdump_collection_on_cpif_interface(interface='x2', capture_file=capture_file, count=count,
                                                        duration=duration, background=background,
                                                        timeout=timeout, bts_id=bts_id,
                                                        additional_options=additional_options)

    def start_tcpdump_collection_on_fronthaul_cpif_interface(self, capture_file, count=0, duration=0,
                                                             background=False, timeout=300, bts_id=0,
                                                             additional_options=None):

        self.start_tcpdump_collection_on_cpif_interface(interface='fronthaul', capture_file=capture_file, count=count,
                                                        duration=duration, background=background,
                                                        timeout=timeout, bts_id=bts_id,
                                                        additional_options=additional_options)

    def start_tcpdump_collection_on_backhaul_upue_interface(self, capture_file, count=0, duration=0,
                                                            background=False, timeout=300, bts_id=0,
                                                            additional_options=None):

        self.start_tcpdump_collection_on_upue_interface(interface='backhaul', capture_file=capture_file, count=count,
                                                        duration=duration, background=background,
                                                        timeout=timeout, bts_id=bts_id,
                                                        additional_options=additional_options)

    @load_moler_configuration_from_tl()
    def stop_tcpdump_collection_on_cpif_interface(self, bts_id=0):
        """
        Optional keyword for stopping the tcpdump collection on the CPIF interface in the chosen moment
        :param bts_id:    BTS ID - related to TestLine configuration
        """
        gnb = DeviceFactory.get_device(format(device_aliases.ssh_gnb_cu.format(bts_id)))
        gnb.goto_state("CPIF")
        stop_tcpdump_on_device(device=gnb, kill_by_sudo=True)

    @load_moler_configuration_from_tl()
    def stop_tcpdump_collection_on_upue_interface(self, bts_id=0):
        """
        Optional keyword for stopping the tcpdump collection on the UPUE interface in the chosen moment
        :param bts_id:    BTS ID - related to TestLine configuration
        """
        gnb = DeviceFactory.get_device(format(device_aliases.ssh_gnb_cu.format(bts_id)))
        gnb.goto_state("UPUE")
        stop_tcpdump_on_device(device=gnb, kill_by_sudo=True)
